const env = vars.env || undefined;
const hits = await tools.logs_search({ env, query: JSON.stringify(String(vars.id)), from: vars.window, size: 200 });
const lines = hits.preview || [];
const traceIds = [...new Set(lines.map(l => l.trace || l.traceId || l.trace_id || l['trace.id']).filter(Boolean))];
const trace = traceIds.length ? await tools.logs_trace({ env, trace: traceIds[0], from: vars.window }).catch(e => ({ error: e.message })) : null;
test('the id appears in the logs', () => expect(hits.total ?? 0).toBeGreaterThan(0));
return { id: vars.id, found: hits.total ?? 0, services: (hits.services || []).map(s => `${s.key}: ${s.count}`), levels: (hits.levels || []).map(l => `${l.key}: ${l.count}`), traceIds, trace: trace && (trace.view || trace.error), logs: hits.view, kibana: hits.kibana };
